3	//! This crate defines the [`PixiSpec`] type which represents a package
4	//! specification for pixi.
5	//!
6	//! The `PixiSpec` type represents the user input for a package. It can
7	//! represent both source and binary packages. The `PixiSpec` type can
8	//! optionally be converted to a `NamelessMatchSpec` which is used to match
9	//! binary packages.
10	
11	mod detailed;
12	mod git;
13	mod path;
14	mod toml;
15	mod url;
16	
17	use std::{path::PathBuf, str::FromStr};
18	
19	pub use detailed::DetailedSpec;
20	pub use git::{GitReference, GitReferenceError, GitSpec};
21	use itertools::Either;
22	pub use path::{PathBinarySpec, PathSourceSpec, PathSpec};
23	use rattler_conda_types::{
24	    ChannelConfig, NamedChannelOrUrl, NamelessMatchSpec, ParseChannelError, VersionSpec,
25	};
26	use thiserror::Error;
27	pub use toml::TomlSpec;
28	pub use url::{UrlBinarySpec, UrlSourceSpec, UrlSpec};
29	
30	/// An error that is returned when a spec cannot be converted into another spec
31	/// type.
32	#[derive(Debug, Error)]
33	pub enum SpecConversionError {
34	    /// The root directory is not an absolute path
35	    #[error("root directory from channel config is not an absolute path")]
36	    NonAbsoluteRootDir(PathBuf),
37	
38	    /// The root directory is not UTF-8 encoded.
39	    #[error("root directory of channel config is not utf8 encoded")]
40	    NotUtf8RootDir(PathBuf),
41	
42	    /// Encountered an invalid path
43	    #[error("invalid path '{0}'")]
44	    InvalidPath(String),
45	
46	    /// Encountered an invalid channel url or path
47	    #[error("invalid channel '{0}'")]
48	    InvalidChannel(#[from] ParseChannelError),
49	}
50	
51	/// A package specification for pixi.
52	///
53	/// This type can represent both source and binary packages. Use the
54	/// [`Self::try_into_nameless_match_spec`] method to convert this type into a
55	/// type that only represents binary packages.
56	#[derive(Debug, Clone, Hash, ::serde::Serialize, PartialEq, Eq)]
57	#[serde(untagged)]
58	pub enum PixiSpec {
59	    /// The spec is represented solely by a version string. The package should
60	    /// be retrieved from a channel.
61	    ///
62	    /// This is similar to the `DetailedVersion` variant but with a simplified
63	    /// version spec.
64	    Version(VersionSpec),
65	
66	    /// The spec is represented by a detailed version spec. The package should
67	    /// be retrieved from a channel.
68	    DetailedVersion(DetailedSpec),
69	
70	    /// The spec is represented as an archive that can be downloaded from the
71	    /// specified URL. The package should be retrieved from the URL and can
72	    /// either represent a source or binary package depending on the archive
73	    /// type.
74	    Url(UrlSpec),
75	
76	    /// The spec is represented as a git repository. The package represents a
77	    /// source distribution of some kind.
78	    Git(GitSpec),
79	
80	    /// The spec is represented as a local path. The package should be retrieved
81	    /// from the local filesystem. The package can be either a source or binary
82	    /// package.
83	    Path(PathSpec),
84	}
85	
86	impl Default for PixiSpec {
87	    fn default() -> Self {
88	        PixiSpec::Version(VersionSpec::Any)
89	    }
90	}
91	
92	impl From<VersionSpec> for PixiSpec {
93	    fn from(value: VersionSpec) -> Self {
94	        Self::Version(value)
95	    }
96	}
97	
98	impl PixiSpec {
99	    /// Convert a [`NamelessMatchSpec`] into a [`PixiSpec`].
100	    pub fn from_nameless_matchspec(
101	        spec: NamelessMatchSpec,
102	        channel_config: &ChannelConfig,
103	    ) -> Self {
104	        if let Some(url) = spec.url {
105	            Self::Url(UrlSpec {
106	                url,
107	                md5: spec.md5,
108	                sha256: spec.sha256,
109	            })
110	        } else if spec.build.is_none()
111	            && spec.build_number.is_none()
112	            && spec.file_name.is_none()
113	            && spec.channel.is_none()
114	            && spec.subdir.is_none()
115	            && spec.md5.is_none()
116	            && spec.sha256.is_none()
117	        {
118	            Self::Version(spec.version.unwrap_or(VersionSpec::Any))
119	        } else {
120	            Self::DetailedVersion(DetailedSpec {
121	                version: spec.version,
122	                build: spec.build,
123	                build_number: spec.build_number,
124	                file_name: spec.file_name,
125	                channel: spec.channel.map(|c| {
126	                    NamedChannelOrUrl::from_str(&channel_config.canonical_name(c.base_url.url()))
127	                        .unwrap()
128	                }),
129	                subdir: spec.subdir,
130	                md5: spec.md5,
131	                sha256: spec.sha256,
132	            })
133	        }
134	    }
135	
136	    /// Returns true if this spec has a version spec. `*` does not count as a
137	    /// valid version spec.
138	    pub fn has_version_spec(&self) -> bool {
139	        match self {
140	            Self::Version(v) => v != &VersionSpec::Any,
141	            Self::DetailedVersion(v) => v.version.as_ref().is_some_and(|v| v != &VersionSpec::Any),
142	            _ => false,
143	        }
144	    }
145	
146	    /// Returns a [`VersionSpec`] if this instance is a version spec.
147	    pub fn as_version_spec(&self) -> Option<&VersionSpec> {
148	        match self {
149	            Self::Version(v) => Some(v),
150	            Self::DetailedVersion(v) => v.version.as_ref(),
151	            _ => None,
152	        }
153	    }
154	
155	    /// Returns a [`DetailedSpec`] if this instance is a detailed version
156	    /// spec.
157	    pub fn as_detailed(&self) -> Option<&DetailedSpec> {
158	        match self {
159	            Self::DetailedVersion(v) => Some(v),
160	            _ => None,
161	        }
162	    }
163	
164	    /// Returns a [`UrlSpec`] if this instance is a detailed version spec.
165	    pub fn as_url(&self) -> Option<&UrlSpec> {
166	        match self {
167	            Self::Url(v) => Some(v),
168	            _ => None,
169	        }
170	    }
171	
172	    /// Returns a [`GitSpec`] if this instance is a git spec.
173	    pub fn as_git(&self) -> Option<&GitSpec> {
174	        match self {
175	            Self::Git(v) => Some(v),
176	            _ => None,
177	        }
178	    }
179	
180	    /// Returns a [`PathSpec`] if this instance is a path spec.
181	    pub fn as_path(&self) -> Option<&PathSpec> {
182	        match self {
183	            Self::Path(v) => Some(v),
184	            _ => None,
185	        }
186	    }
187	
188	    /// Converts this instance into a [`VersionSpec`] if possible.
189	    pub fn into_version(self) -> Option<VersionSpec> {
190	        match self {
191	            Self::Version(v) => Some(v),
192	            Self::DetailedVersion(DetailedSpec {
193	                version: Some(v), ..
194	            }) => Some(v),
195	            _ => None,
196	        }
197	    }
198	
199	    /// Converts this instance into a [`DetailedSpec`] if possible.
200	    pub fn into_detailed(self) -> Option<DetailedSpec> {
201	        match self {
202	            Self::DetailedVersion(v) => Some(v),
203	            Self::Version(v) => Some(DetailedSpec {
204	                version: Some(v),
205	                ..DetailedSpec::default()
206	            }),
207	            _ => None,
208	        }
209	    }
210	
211	    /// Converts this instance into a [`UrlSpec`] if possible.
212	    pub fn into_url(self) -> Option<UrlSpec> {
213	        match self {
214	            Self::Url(v) => Some(v),
215	            _ => None,
216	        }
217	    }
